<?php require_once '../../includes/auth.php';require_once '../../config/conexion.php';$rows=$pdo->query('SELECT * FROM v_tablero_ucin ORDER BY numero_espacio')->fetchAll();$total=count($rows);$ocup=count(array_filter($rows,fn($r)=>$r['estado_espacio']==='Ocupada'));$disp=count(array_filter($rows,fn($r)=>$r['estado_espacio']==='Disponible'));$mant=$total-$ocup-$disp;$titulo='Reporte UCIN';require '../../includes/header.php';?><div class="acciones"><h1>Reporte de ocupación y estado clínico — UCIN</h1><button class="boton principal" onclick="window.print()">Imprimir / Guardar como PDF</button></div><p>Hospital Universitario La Salle · Generado: <?= date('d/m/Y H:i') ?> · Usuario: <?= h($_SESSION['nombre_completo']) ?></p><div class="kpis"><div class="kpi">Total: <?= $total ?></div><div class="kpi">Ocupados: <?= $ocup ?></div><div class="kpi">Disponibles: <?= $disp ?></div><div class="kpi">Mantenimiento: <?= $mant ?></div><div class="kpi">Ocupación: <?= $total?round($ocup/$total*100,1):0 ?>%</div></div><div class="panel tabla-wrap"><table><thead><tr><th>Espacio</th><th>Equipo</th><th>Zona</th><th>Estado</th><th>Neonato</th><th>Semanas</th><th>Peso nac./actual</th><th>Estado clínico</th><th>Médico</th><th>Días</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= h($r['numero_espacio']) ?></td><td><?= h($r['tipo_equipo']) ?></td><td><?= h($r['zona_ucin']) ?></td><td><?= h($r['estado_espacio']) ?></td><td><?= h($r['nombre_neonato']?:'—') ?></td><td><?= h($r['semanas_gestacion']??'—') ?></td><td><?= h($r['peso_nacer_gramos']??'—') ?>/<?= h($r['peso_actual_gramos']??'—') ?></td><td><?= h($r['estado_clinico']??'—') ?></td><td><?= h($r['medico_tratante']??'—') ?></td><td><?= h($r['dias_estancia']??'—') ?></td></tr><?php endforeach;?></tbody></table></div><p class="confidencial">Documento con datos médicos confidenciales y neonatales. Uso exclusivo del personal autorizado de la UCIN.</p><style>@media print{.topbar,.menu,.pie,.acciones button{display:none!important}.